import {setting,setSetting} from './db.mjs';
import {createFieldJob,updateFieldJob,evaluateFieldJob,exportFieldJob,importFieldJob} from './loop-field-model.mjs';
import * as fieldStore from './loop-field-store.mjs';
import {processLoopPhotos,parseLoopListText,getLoopPhotoReadiness} from './loop-photo-import.mjs';

const UI_KEY='loop-field-ui-v1';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const clone=value=>JSON.parse(JSON.stringify(value));
const uid=()=>globalThis.crypto?.randomUUID?.()||'field-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const button=(action,label,attrs='',kind='secondary')=>`<button type="button" class="${kind}" data-field-action="${action}" data-field-focus="${esc(action+'|'+attrs.match(/data-id="([^"]*)"/)?.[1])}" ${attrs}>${label}</button>`;
const input=(name,label,value='',attrs='')=>`<label class="pl-field">${label}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
const textValue=value=>typeof value==='string'?value:value?.detail||value?.summary||value?.text||value?.label||value?.message||'';
const dateLabel=value=>value?new Date(value).toLocaleString('en-GB'):'Time not recorded';
const localDate=value=>{if(!value)return '';const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,19);};
const numeric=value=>value===''||value==null?null:Number(value);
const sourceBase={recordId:'protec-aee99ea8ed2b',title:'Protec Algo-Tec 6500/6600 — Commissioning manual',edition:'RDM0002/2_4 · 11 December 2017',url:'https://www.acornfiresecurity.com/index.php?filename=6500-commissioning-manual.pdf&route=extension%2Fmodule%2Fdocument%2Fdownload',sha256:'0e841fa49b0a24fac91d5c7cde6987e4b311974d0a96ee78643e0ca17a2bfeb0'};
const steps=[['capture','1 · Capture'],['devices','2 · Review'],['sections','3 · Sections'],['tests','4 · Readings'],['handover','5 · Handover']];

export function createLoopFieldLogController({app,read=setting,write=setSetting,store=fieldStore,onSource=null,openResources=null,toast=()=>{},isActive=()=>true}={}){
 let mount=null,loaded=false,loading=null,epoch=0,selectionEpoch=0,jobs=[],job=null,queue=Promise.resolve(),saving=0,saveError='',error='',message='',ui={selectedJobId:'',jobs:{}},revisions=new Map(),readiness=null,processing=null,processingStatus=null,pendingPhoto=null,pendingDelete=false,creating=false,photoUrl='',photoUrlId='',photoLoading='',photoError='',draftTimer=null,loadError='',unsavedJob=false;
 const active=()=>isActive()&&mount?.isConnected;
 const busy=()=>!!processing;
 const currentUI=()=>{if(!job)return {};return ui.jobs[job.id]??=( {step:'capture',selectedPhotoId:'',manualRows:[],paste:'',testDraft:{},sectionDraft:{},jobDraft:{},handoverDraft:{}} );};
 const currentPhoto=()=>job?.photos?.find(photo=>photo.id===currentUI().selectedPhotoId)||job?.photos?.[0]||null;
 const status=()=>saveError?`${esc(saveError)} ${button('retry-save','Retry save')}`:saving?'Saving on this device…':job?'Job saved on this device':'Create a job to start a local log';
 function updateStatus(){if(!active())return;const element=mount.querySelector('#lfl-save-status');if(element){element.innerHTML=status();element.classList.toggle('pl-error',!!saveError);}}
 function remember(next){const index=jobs.findIndex(item=>item.id===next.id);if(index<0)jobs.unshift(next);else jobs[index]=next;}
 function persist(next=job,{photo=null}={}){
  if(photo&&next)pendingPhoto={...photo,jobId:next.id};
  const snapshot=next?clone(next):null,photoCommit=snapshot&&pendingPhoto?.jobId===snapshot.id?{id:pendingPhoto.id,blob:pendingPhoto.blob}:null;ui.selectedJobId=job?.id||'';const uiSnapshot=clone(ui);if(snapshot)unsavedJob=true;saving++;updateStatus();
  queue=queue.catch(()=>{}).then(async()=>{
   if(snapshot){const expectedRevision=revisions.get(snapshot.id)??snapshot.revision??0;const committed=await store.saveJob({...snapshot,revision:expectedRevision},{expectedRevision,...(photoCommit?{photo:photoCommit}:{})});revisions.set(snapshot.id,committed.revision);if(photoCommit&&pendingPhoto?.id===photoCommit.id)pendingPhoto=null;if(job?.id===snapshot.id)job.revision=committed.revision;const listed=jobs.find(item=>item.id===snapshot.id);if(listed)listed.revision=committed.revision;unsavedJob=false;}
   await write(UI_KEY,uiSnapshot);if(snapshot||!unsavedJob)saveError='';
  }).catch(err=>{if(snapshot)unsavedJob=true;saveError=err?.name==='QuotaExceededError'||String(err?.code).includes('FULL')?'Device storage is full. Your latest work is still on screen. Export the log, make space and retry.':`Couldn’t save this job. ${err?.message||'The previous saved version is kept.'}`;}).finally(()=>{saving--;updateStatus();});return queue;
 }
 function saveDraftSoon(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{draftTimer=null;persist(null);},450);}
 async function flush(){if(draftTimer){clearTimeout(draftTimer);draftTimer=null;await persist(null);}await queue;}
 function change(action){job=updateFieldJob(job,action);remember(job);error='';message='';persist();paint();}
 function view(){return evaluateFieldJob(job);}
 function setStep(step){currentUI().step=step;persist(null);paint();mount.querySelector('.lfl-step-heading')?.scrollIntoView({block:'start',behavior:'instant'});}
 function revokePhoto(){if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl='';photoUrlId='';photoError='';photoLoading='';}
 async function ensurePhoto(){const photo=currentPhoto();if(!active()||!photo||currentUI().step!=='capture')return;if(photoUrlId===photo.id||photoLoading===photo.id)return;revokePhoto();photoLoading=photo.id;const own=epoch,id=job.id;try{const blob=pendingPhoto?.jobId===id&&pendingPhoto.id===photo.id?pendingPhoto.blob:await store.loadPhoto(id,photo.id);if(!active()||own!==epoch||job?.id!==id||currentPhoto()?.id!==photo.id)return;if(!blob){photoError='The original image is not stored on this device. Imported JSON retains text and provenance but excludes photo files.';photoUrlId=photo.id;}else if(!/^image\/(?:jpeg|png|webp|gif|avif|bmp|heic|heif)$/i.test(blob.type||photo.mimeType||'')){photoError='This format is not shown in the app. Save the original if needed, or add a JPEG/PNG photo. Existing text is retained.';photoUrlId=photo.id;}else{photoUrl=URL.createObjectURL(blob);photoUrlId=photo.id;}}catch(err){photoError=`Couldn’t open the photo. ${err.message}`;photoUrlId=photo.id;}finally{if(photoLoading===photo.id)photoLoading='';if(active()&&own===epoch)paint();}}
 async function refreshReadiness(){try{readiness=await getLoopPhotoReadiness();}catch(err){readiness={ready:false,supported:false,message:err.message};}if(active()){const target=mount.querySelector('#lfl-ocr-readiness');if(target)target.innerHTML=resourceStatus();}}
 function resourceStatus(){return `<span>${esc(readiness?.message||'Checking local photo-reading resources…')}</span>${!readiness?.ready?button('resources','Set up offline OCR','','subtle'):''}`;}
 function sourceInfo(){return `<details class="lfl-sources" data-field-disclosure="sources"><summary>6500 menu reference & limits</summary><p>Protec RDM0002/2_4, 11 December 2017: Tools Menu → Loop Tools → Allocate addresses → select panel, loop card and loop → Map header. The allocation screen has write controls; sorting its list is not allocating an address.</p>${button('source','Allocate addresses / Map · PDF p. 10','data-page="10"','pl-source')}<p>Tools Menu → Diagnostic Tools → Loop Info. The documented counter is <strong>Total Device Missed Replies</strong>. Reset Counts also clears Total Exchange Errors; preserve the previous reading first.</p>${button('source','Loop Info / missed replies · PDF p. 21','data-page="21"','pl-source')}<p>Map values are approximate groups relative to isolators. Tied values do not establish device order. Use a checked drawing or on-site evidence to define an actual section. FINDR does not operate panel controls or tell you how to disconnect wiring.</p><p class="pl-muted">No total-poll counter is established by this source. Optional poll readings must come from a source you identify. Check the installed model and software revision before using menu references.</p></details>`;}
 function header(){return `<header class="lfl-intro"><span class="pl-kicker">Site investigation · your entered evidence</span><h2>Log the real loop.</h2><p>Photograph the list, check the rows, then record what you tested and what changed.</p><p class="lfl-local-note">Photos and OCR stay on this device. Nothing connects to, isolates or controls your panel.</p></header>${sourceInfo()}`;}
 function jobsBar(){return `<div class="lfl-jobs-bar"><label class="pl-field">Saved loop jobs<select id="lfl-job-select"${busy()?' disabled':''}><option value="">Choose a job</option>${jobs.map(item=>`<option value="${esc(item.id)}"${item.id===job?.id?' selected':''}>${esc(item.name)}</option>`).join('')}</select></label>${button('new-job','New job',busy()?'disabled':'')}</div><p id="lfl-save-status" class="pl-save${saveError?' pl-error':''}" role="status">${status()}</p>`;}
 function detailsForm(isNew=false){const draft=isNew?(ui.createDraft||{}):{...job,...currentUI().jobDraft};return `<form id="lfl-job-form" class="pl-form" data-new="${isNew}"><div class="pl-fields">${input('name','Job name',draft.name||'','required maxlength="160" placeholder="e.g. North building — loop 2"')}${input('panel','Panel model',draft.panel??'Protec 6500','required maxlength="120"')}${input('card','Loop card (or unknown)',draft.card||'','required maxlength="80"')}${input('loop','Loop number / label',draft.loop||'','required maxlength="80"')}${input('reference','Site / job reference',draft.reference||'','maxlength="200"')}</div><button type="submit" class="primary">${isNew?'Create local job':'Save job details'}</button></form>`;}
 function controls(){return `<div class="lfl-job-context"><div><strong>${esc(job.name)}</strong><span>${esc(job.panel)} · card ${esc(job.card||'unknown')} · loop ${esc(job.loop||'unknown')}</span></div><details data-field-disclosure="job-options"><summary>Job options</summary>${detailsForm()}<div class="pl-actions">${button('export','Export log — without photo files')}${button('import','Import log JSON')}${button('delete-job','Delete this job','','subtle')}</div><p class="pl-muted">JSON includes readings, row provenance and history. Original photo files stay on this device; save them separately before moving or deleting the job.</p>${pendingDelete?`<div class="pl-notice pl-error"><p>Delete this job and its locally stored photos? Other jobs, manuals and practice exercises are kept.</p>${button('confirm-delete','Delete job and photos','','danger')}${button('cancel-delete','Keep job')}</div>`:''}</details></div><nav class="lfl-steps" aria-label="Site investigation stages">${steps.map(([id,label])=>button('step',label,`data-id="${id}" aria-current="${currentUI().step===id?'step':'false'}"`,'lfl-step')).join('')}</nav>`;}
 function newRow(values={}){return {id:uid(),address:'',mapNode:'',label:'',isolator:'unknown',include:true,sourcePhotoIds:[],...values};}
 function photoRows(photo){const ocr=photo?.ocr||{};return Array.isArray(ocr.reviewRows)?ocr.reviewRows:(ocr.suggestions||[]).map(row=>newRow({id:row.id,address:row.address??'',mapNode:row.map??row.mapNode??'',label:row.locationText??row.label??'',sourcePhotoIds:[photo.id],rawLine:row.rawLine||'',issues:row.issues||[]}));}
 function reviewRows(){const state=currentUI();if(state.reviewManual)return state.manualRows??=[];const photo=currentPhoto();if(!photo)return [];if(!state.photoDrafts)state.photoDrafts={};return state.photoDrafts[photo.id]??=(photoRows(photo));}
 function rowEditor(rows){return `<div class="lfl-review-list">${rows.map(row=>`<fieldset class="lfl-review-row" data-review-row="${esc(row.id)}"><legend>Proposed device row</legend><label class="pl-check"><input type="checkbox" name="include"${row.include!==false?' checked':''}>Include this row when I confirm</label><div class="pl-fields">${input('address','Address',row.address,'inputmode="numeric" maxlength="8"')}${input('mapNode','Map group (blank = unknown)',row.mapNode,'inputmode="numeric" maxlength="8"')}${input('label','Location / device label',row.label,'maxlength="160"')}<label class="pl-field">Isolator shown?<select name="isolator"><option value="unknown"${row.isolator==='unknown'?' selected':''}>Unknown / not established</option><option value="yes"${row.isolator==='yes'?' selected':''}>Yes — checked</option><option value="no"${row.isolator==='no'?' selected':''}>No — checked</option></select></label></div>${row.rawLine?`<details><summary>Original recognised line</summary><p class="lfl-raw-text">${esc(row.rawLine)}</p></details>`:''}${row.issues?.length?`<p class="lfl-caution">Check: ${esc(row.issues.join(' · '))}</p>`:''}${button('remove-draft-row','Remove proposed row',`data-id="${esc(row.id)}"`,'subtle')}</fieldset>`).join('')}</div>`;}
 function capture(){const photo=currentPhoto(),manual=currentUI().reviewManual,rows=reviewRows(),photoList=job.photos||[],ocr=photo?.ocr;return `<section><div class="lfl-step-heading"><span class="pl-kicker">Capture & check</span><h3>Add the loop list.</h3><p>Use several photographs if the list has more than one page. OCR makes proposals; it never confirms a device for you.</p></div><div class="pl-actions">${button('take-photo','Take photo',busy()?'disabled':'','primary')}${button('add-photos','Add photos',busy()?'disabled':'')}${button('manual-rows','Enter rows manually',busy()?'disabled':'')}${button('paste-rows','Paste a table',busy()?'disabled':'')}</div><input id="lfl-photo-files" type="file" accept="image/*" multiple hidden><input id="lfl-camera-file" type="file" accept="image/*" capture="environment" hidden><p id="lfl-ocr-readiness" class="lfl-resource-status">${resourceStatus()}</p>${busy()?`<div id="lfl-processing-status" class="pl-notice" role="status"><strong>${esc(processingStatus?.message||'Preparing your photos…')}</strong>${Number.isFinite(processingStatus?.progress)?`<progress max="1" value="${processingStatus.progress}" aria-label="Actual photo processing progress"></progress>`:''}<p>Original photos are stored locally. Cancelling keeps photos and earlier results already saved.</p>${button('cancel-ocr','Cancel photo reading')}</div>`:''}${currentUI().showPaste?`<form id="lfl-paste-form" class="pl-form"><label class="pl-field">Paste the list, including its column headings<textarea name="text" rows="5" placeholder="Address  Map  Location">${esc(currentUI().paste||'')}</textarea></label><button class="secondary" type="submit">Make editable proposals</button><p class="pl-muted">If the columns cannot be identified, type the rows manually. Unclear text is never treated as a confirmed device.</p></form>`:''}${photoList.length?`<label class="pl-field lfl-photo-picker">Stored photographs<select id="lfl-photo-select">${photoList.map(item=>`<option value="${esc(item.id)}"${item.id===photo?.id?' selected':''}>${esc(item.name)}${item.ocr?.error?' · needs attention':''}</option>`).join('')}</select></label>`:''}${photo&&!manual?`<div class="lfl-photo-review"><div class="lfl-photo-preview">${photoUrl&&photoUrlId===photo.id?`<img src="${esc(photoUrl)}" alt="Your uploaded loop list: ${esc(photo.name)}">`:`<p>${esc(photoError||'Opening your saved photograph…')}</p>`}<div class="pl-actions">${button('save-photo','Save original photo',photo.binaryAvailable===false?'disabled':'')}${button('retry-ocr','Read this photo again',busy()?'disabled':'')}</div></div><div class="lfl-photo-caption"><strong>${esc(photo.name)}</strong><p>${photo.size?Math.ceil(photo.size/1024)+' KB · ':''}${pendingPhoto?.id===photo.id?'Original not yet saved — keep this view open and retry save.':'Original kept locally when its save succeeds.'}</p>${ocr?.error?`<p class="pl-notice pl-error">${esc(ocr.error.message||'This photo could not be read. Review the image or enter its rows manually.')}</p>`:''}${ocr?.state==='pending'?`<p class="pl-notice">Photo saved. ${busy()?'Reading is in progress.':'Reading was interrupted or has not completed. Retry this photo, or enter its rows manually.'}</p>`:''}${ocr?.warnings?.length?`<ul>${ocr.warnings.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}<details data-field-disclosure="ocr-text"><summary>OCR text & unparsed lines</summary><pre class="lfl-raw-text">${esc(ocr?.rawText||'No recognised text saved yet.')}</pre>${ocr?.unparsedLines?.length?`<p>Not assigned to a row:</p><pre class="lfl-raw-text">${esc(ocr.unparsedLines.map(textValue).join('\n'))}</pre>`:''}</details></div></div>`:''}${rows.length?`<div class="lfl-proposals"><div class="pl-section-heading"><h3>${manual?'Manual proposals':'Unconfirmed photo proposals'}</h3><span>${rows.length} rows</span></div><p class="pl-notice">Check every selected address and Map value against the original. Correct any misread digits, labels or duplicate addresses before confirming.</p>${rowEditor(rows)}<div class="pl-actions">${button('add-draft-row','Add another proposed row')}</div><label class="pl-check lfl-confirm-check"><input type="checkbox" id="lfl-review-confirmed">I checked these rows against the original and confirmed they belong to ${esc(job.panel)}, card ${esc(job.card||'unknown')}, loop ${esc(job.loop||'unknown')}.</label>${button('confirm-rows','Confirm checked rows into the device list',busy()?'disabled':'','primary')}</div>`:!busy()?'<p class="pl-muted">There are no proposed rows yet. Add a photograph, paste text, or enter a row manually.</p>':''}<div class="lfl-next"><span>${job.devices.length} engineer-confirmed devices</span>${button('step','Review confirmed list','data-id="devices"')}</div></section>`;}
 function devices(){const result=view(),scope={...(job.inventoryScope||{}),...(currentUI().inventoryDraft||{})};return `<section><div class="lfl-step-heading"><span class="pl-kicker">Engineer-confirmed rows</span><h3>${job.devices.length} devices in this job</h3><p>Map groups are not an exact wiring order. A partial list cannot establish whole-loop coverage.</p></div>${(result.conflicts||[]).length?`<div class="pl-notice pl-error"><strong>Resolve these conflicts</strong><ul>${result.conflicts.map(item=>`<li>${esc(textValue(item))}</li>`).join('')}</ul></div>`:''}<form id="lfl-inventory-form" class="pl-form lfl-panel"><label class="pl-check"><input name="inventoryComplete" type="checkbox"${scope.inventoryComplete||job.inventoryComplete?' checked':''}>All loop-list pages and the complete device inventory have been checked.</label>${input('expectedDeviceCount','Expected / logged device count, if known',scope.expectedDeviceCount??job.expectedDeviceCount??'','type="number" min="0" step="1" inputmode="numeric"')}<label class="pl-field">How was completeness checked?<textarea name="confirmation" rows="2" maxlength="2000">${esc(scope.confirmation||job.inventoryConfirmation||'')}</textarea></label><button class="secondary" type="submit">Record inventory scope</button></form><div class="lfl-map-groups">${(result.mapGroups||[]).map(group=>`<article><strong>${esc(group.label??(group.node==null?'Unknown Map group':'Map group '+group.node))}</strong><p>${(group.devices||[]).map(device=>'Address '+esc(device.address)).filter(Boolean).join(' · ')}</p><small>Grouping only; no physical sequence inferred.</small></article>`).join('')}</div><div class="lfl-device-cards">${job.devices.map(device=>`<article><div><strong>Address ${esc(device.address)}</strong><p>${esc(device.label||'No location label')}</p><small>Map ${device.mapNode==null?'unknown':esc(device.mapNode)} · isolator ${device.isolator===true?'confirmed':device.isolator===false?'confirmed absent':'unknown'}</small></div>${button('edit-device','Correct row',`data-id="${esc(device.id)}"`)}</article>`).join('')}</div>${deviceEditor()}<div class="lfl-next">${button('step','Add more photographs or rows','data-id="capture"')}${button('step','Define tested sections','data-id="sections"','primary')}</div></section>`;}
 function deviceEditor(){const savedDevice=job.devices.find(item=>item.id===currentUI().editDevice);if(!savedDevice)return '';const draft=currentUI().deviceDraft||{},device={...savedDevice,...draft,isolator:draft.isolator==='yes'?true:draft.isolator==='no'?false:draft.isolator==='unknown'?null:savedDevice.isolator};return `<form id="lfl-device-form" class="pl-form lfl-panel" data-id="${esc(device.id)}"><h3>Correct address ${esc(device.address)}</h3><div class="pl-fields">${input('address','Address',device.address,'required inputmode="numeric"')}${input('mapNode','Map group (blank = unknown)',device.mapNode??'','inputmode="numeric"')}${input('label','Location / label',device.label||'','maxlength="160"')}<label class="pl-field">Isolator<select name="isolator"><option value="unknown"${device.isolator==null?' selected':''}>Unknown</option><option value="yes"${device.isolator===true?' selected':''}>Confirmed present</option><option value="no"${device.isolator===false?' selected':''}>Confirmed absent</option></select></label></div>${input('reason','Why is this row changing?',draft.reason||'','required maxlength="2000"')}<div class="pl-actions"><button type="submit" class="primary">Save correction with history</button>${button('remove-device','Remove row with reason',`data-id="${esc(device.id)}"`,'subtle')}${button('cancel-device','Cancel')}</div><p class="pl-muted">Previous values remain in the log. Dependent tests may need review after the correction.</p></form>`;}
 function deviceChoices(name,selected=[]){return `<div class="lfl-device-choices">${job.devices.map(device=>`<label class="pl-check"><input type="checkbox" name="${name}" value="${esc(device.id)}"${selected.includes(device.id)?' checked':''}><span><strong>${esc(device.address)}</strong> ${esc(device.label||'Unlabelled device')}<small>Map ${device.mapNode==null?'unknown':esc(device.mapNode)}</small></span></label>`).join('')}</div>`;}
 function sectionLatest(section){const latest=view().tests.filter(test=>test.sectionIds.includes(section.id)).at(-1);if(!latest)return '<p class="lfl-section-reading">No observation associated with this section yet.</p>';const label=latest.needsReview?'Observation needs review':latest.delta==null?'Delta not established':latest.delta===0?'No new missed replies in this window':`${latest.delta} additional missed replies`;return `<div class="lfl-section-reading"><span>${latest.sectionIds.length>1?'Latest test including this section':'Latest recorded test for this section'}</span><strong>${esc(label)}</strong><small>${dateLabel(latest.endedAt||latest.startedAt)} · ${latest.polledDeviceIds.length} actually polled · ${latest.excludedDeviceIds.length} excluded · ${latest.unavailableDeviceIds.length} unavailable</small><p>${latest.sectionIds.length>1?'This reading covers multiple sections and is not attributed to this section alone.':'This observation does not confirm a cause, healthy loop or repair.'}</p></div>`;}
 function sections(){const draft=currentUI().sectionDraft||{},editing=job.sections.find(item=>item.id===draft.id);return `<section><div class="lfl-step-heading"><span class="pl-kicker">Independent physical evidence</span><h3>Which part are you testing?</h3><p>Name actual boundaries and record how you identified them. Map numbers alone do not prove a physical section.</p></div><div class="lfl-section-cards">${job.sections.map(section=>`<article><div><span class="lfl-state">${section.topologyConfirmed?'Engineer-confirmed topology':'Unverified physical section'}</span><h3>${esc(section.name)}</h3><p>${esc(section.topologyEvidence||'No independent topology evidence recorded.')}</p><small>${section.deviceIds.map(id=>{const device=job.devices.find(item=>item.id===id);return device?'Address '+device.address:'Removed device';}).join(' · ')}</small>${sectionLatest(section)}</div>${button('edit-section','Review / correct section',`data-id="${esc(section.id)}"`)}</article>`).join('')}</div><form id="lfl-section-form" class="pl-form lfl-panel" data-id="${esc(draft.id||'')}"><h3>${editing?'Correct this section':'Record a physical section'}</h3>${input('name','Section name',draft.name||'','required maxlength="160" placeholder="e.g. Between stair lobby and workshop"')}<label class="pl-field">Boundaries and evidence<textarea name="topologyEvidence" rows="3" maxlength="4000" placeholder="Drawing reference, labelled isolators, traced route, and what remains uncertain">${esc(draft.topologyEvidence||'')}</textarea></label><label class="pl-check"><input name="topologyConfirmed" type="checkbox"${draft.topologyConfirmed?' checked':''}>I checked these boundaries independently of the address and Map numbers.</label><fieldset class="lfl-plain-fieldset"><legend>Devices associated with this section</legend>${deviceChoices('deviceIds',draft.deviceIds||[])}</fieldset>${editing?input('reason','Why is this section changing?',draft.reason||'','required maxlength="2000"'):''}<div class="pl-actions"><button class="primary" type="submit"${job.devices.length?'':' disabled'}>${editing?'Save correction with history':'Save section'}</button>${button('clear-section','Clear section form')}</div><p class="pl-muted">You can save an unverified section, but FINDR will not treat it as proven topology for comparison.</p></form><div class="lfl-next">${button('step','Record actual readings','data-id="tests"','primary')}</div></section>`;}
 function coverageRows(draft){return `<div class="lfl-coverage-list">${job.devices.map(device=>`<label class="lfl-coverage-row"><span><strong>Address ${esc(device.address)}</strong><small>${esc(device.label||'Unlabelled device')}</small></span><select name="coverage:${esc(device.id)}" aria-label="Actual coverage for address ${esc(device.address)}"><option value="unavailable"${!draft.coverage?.[device.id]||draft.coverage[device.id]==='unavailable'?' selected':''}>Not established / unavailable</option><option value="polled"${draft.coverage?.[device.id]==='polled'?' selected':''}>Actually polled</option><option value="excluded"${draft.coverage?.[device.id]==='excluded'?' selected':''}>Deliberately excluded</option></select></label>`).join('')}</div>`;}
 function testForm(){const draft=currentUI().testDraft||{},editing=job.tests.find(item=>item.id===draft.id);return `<form id="lfl-test-form" class="pl-form lfl-panel" data-id="${esc(draft.id||'')}"><h3>${editing?'Review / correct observation':'Record a real observation'}</h3><p class="pl-muted">Enter the readings you saw. Times can remain unknown, but then FINDR cannot compare rates or equal observation windows.</p><div class="pl-fields"><label class="pl-field">Start time<input name="startedAt" type="datetime-local" step="1" value="${esc(draft.startedAt||'')}"></label><label class="pl-field">End time<input name="endedAt" type="datetime-local" step="1" value="${esc(draft.endedAt||'')}"></label></div><div class="pl-actions">${button('time-start','Record start time now')}${button('time-end','Record end time now')}</div><div class="pl-fields">${input('missedBefore','Missed replies at start (blank = unknown)',draft.missedBefore??'','type="number" min="0" step="1" inputmode="numeric"')}${input('missedAfter','Missed replies at end',draft.missedAfter??'','required type="number" min="0" step="1" inputmode="numeric"')}<label class="pl-field">Counters reset?<select name="reset"><option value="none"${!draft.reset||draft.reset==='none'?' selected':''}>Not reset during this window</option><option value="before-window"${draft.reset==='before-window'?' selected':''}>Reset before the window started</option><option value="during-window"${draft.reset==='during-window'?' selected':''}>Reset during the window / timing unclear</option></select></label>${input('resetNote','Reset time / explanation',draft.resetNote||'','maxlength="2000"')}</div><details data-field-disclosure="optional-polls"><summary>Optional actual poll-count readings</summary><p class="pl-muted">No poll count is calculated from elapsed time. Only enter counts from a real source you identify.</p><div class="pl-fields">${input('pollsBefore','Poll count at start',draft.pollsBefore??'','type="number" min="0" step="1" inputmode="numeric"')}${input('pollsAfter','Poll count at end',draft.pollsAfter??'','type="number" min="0" step="1" inputmode="numeric"')}</div>${input('pollsSource','Source of actual poll readings',draft.pollsSource||'','maxlength="2000"')}</details><label class="pl-field">Operating conditions & changes<textarea name="conditions" rows="3" required maxlength="4000" placeholder="What was connected, isolated or unavailable; feed conditions; exact indications; what changed since the previous reading">${esc(draft.conditions||'')}</textarea></label><fieldset class="lfl-plain-fieldset"><legend>Physical sections involved, if established</legend>${job.sections.length?job.sections.map(section=>`<label class="pl-check"><input name="sectionIds" type="checkbox" value="${esc(section.id)}"${draft.sectionIds?.includes(section.id)?' checked':''}>${esc(section.name)}${section.topologyConfirmed?'':' · unverified'}</label>`).join(''):'<p class="pl-muted">No physical section has been recorded. Whole-loop or incomplete observations can still be logged honestly.</p>'}</fieldset><details class="lfl-coverage" data-field-disclosure="coverage" open><summary>Which devices were actually covered?</summary><p class="pl-muted">Nothing is marked polled automatically. Excluded or unavailable devices are not evidence of a healthy device.</p>${button('coverage-all-polled','I checked: all listed devices were polled','','subtle')}${coverageRows(draft)}</details><label class="pl-check"><input name="conditionsConfirmed" type="checkbox"${draft.conditionsConfirmed?' checked':''}>I have checked the operating conditions and actual device coverage for this reading.</label><label class="pl-field">Observation notes<textarea name="notes" rows="2" maxlength="4000">${esc(draft.notes||'')}</textarea></label>${editing?input('reason','What did you review or correct?',draft.reason||'','required maxlength="2000"'):''}<div class="pl-actions"><button type="submit" class="primary"${job.devices.length?'':' disabled'}>${editing?'Save reviewed observation':'Save observation'}</button>${button('clear-test','Clear observation form')}</div></form>`;}
 function tests(){const result=view();return `<section><div class="lfl-step-heading"><span class="pl-kicker">Actual entered readings</span><h3>Record what changed.</h3><p>Keep the start and end counters, interval and coverage together. Resetting a counter or polling fewer devices is not proof of improvement.</p></div>${testForm()}<div class="lfl-test-list"><h3>Saved observations · ${job.tests.length}</h3>${(result.tests||[]).slice().reverse().map(test=>`<article><header><strong>${dateLabel(test.endedAt||test.startedAt)}</strong>${test.needsReview?'<span class="lfl-state is-warning">Needs review after a correction</span>':''}</header><div class="lfl-reading-pair"><span>${test.missedBefore==null?'Unknown':esc(test.missedBefore)} → ${esc(test.missedAfter)}<small>actual entered counter readings</small></span><span>${test.delta==null?'Not comparable':'+'+test.delta}<small>${test.delta==null?'no supported delta':'additional missed replies'}</small></span></div><p>${esc(textValue(test.interpretation)||'Read this observation with its operating conditions and coverage.')}</p><p class="pl-muted"><strong>Sections:</strong> ${test.sectionSnapshot?.length?test.sectionSnapshot.map(section=>esc(section.name)).join(' · '):'No physical section specified'}</p><p class="pl-muted">${esc(test.conditions)}</p>${test.pollsSource?`<p class="pl-muted">Actual poll source: ${esc(test.pollsSource)} · ${test.pollsBefore??'unknown'} → ${test.pollsAfter??'unknown'}</p>`:''}${test.reasons?.length?`<ul class="lfl-reasons">${test.reasons.map(item=>`<li>${esc(textValue(item))}</li>`).join('')}</ul>`:''}<details data-field-disclosure="test-${esc(test.id)}"><summary>Times, coverage & provenance</summary><p>Start: ${dateLabel(test.startedAt)}<br>End: ${dateLabel(test.endedAt)}<br>Reset: ${esc(test.reset)}</p><p>Polled: ${test.polledDeviceIds?.length||0} · excluded: ${test.excludedDeviceIds?.length||0} · unavailable / not established: ${test.unavailableDeviceIds?.length||0}</p><p>${esc(test.notes||'No additional observation notes.')}</p></details>${button('edit-test','Review / correct observation',`data-id="${esc(test.id)}"`)}</article>`).join('')}</div><details class="lfl-comparisons" data-field-disclosure="comparisons"><summary>Compare recorded windows</summary><p class="pl-muted">Comparisons depend on real interval, reset state, checked conditions, inventory scope and coverage. Different sections remain different coverage; a smaller total is not a confirmed cause.</p>${(result.comparisons||[]).slice(-20).map(item=>`<article><strong>${item.comparable?'Comparison available':'Comparison withheld'}</strong><p>${esc(item.summary||'Review both observations before drawing a conclusion.')}</p>${item.reasons?.length?`<ul>${item.reasons.map(reason=>`<li>${esc(textValue(reason))}</li>`).join('')}</ul>`:''}</article>`).join('')||'<p>No pair of observations is available yet.</p>'}</details><div class="lfl-next">${button('step','Prepare handover & restoration','data-id="handover"','primary')}</div></section>`;}
 function handover(){const result=view(),draft=currentUI().handoverDraft||{};return `<section><div class="lfl-step-heading"><span class="pl-kicker">Leave a useful next step</span><h3>Findings, impairments & restoration.</h3><p>A low or zero change is only an observation. Keep the suspected area, confirmed cause, repair and functional retest separate.</p></div><div class="lfl-outstanding"><h3>Still outstanding</h3><ul>${(result.outstanding||[]).map(item=>`<li>${esc(textValue(item))}</li>`).join('')||'<li>No additional model-generated checks. Review the actual site status before handover.</li>'}</ul></div><form id="lfl-impairment-form" class="pl-form lfl-panel"><h3>Record a system impairment or introduced isolation</h3><label class="pl-field">What remains affected?<textarea name="description" rows="2" required maxlength="4000" placeholder="Describe the actual impairment, affected protection and required restoration"></textarea></label><button type="submit" class="secondary">Add impairment to the log</button></form><div class="lfl-impairment-list">${job.impairments.map(item=>`<article><strong>${esc(item.description)}</strong><p>${item.restoredAt?'Restoration recorded '+dateLabel(item.restoredAt):'Restoration not recorded'}</p>${item.restoredAt?`<p>${esc(item.restorationEvidence)}</p>`:`<form class="lfl-restoration-form pl-form" data-id="${esc(item.id)}"><label class="pl-field">Restoration evidence & functional retest<textarea name="evidence" rows="2" required maxlength="4000" placeholder="What was restored, the functional checks completed, and any remaining fault"></textarea></label><button class="secondary" type="submit">Record this restoration</button></form>`}</article>`).join('')}</div><form id="lfl-handover-form" class="pl-form lfl-panel"><h3>Engineer handover</h3><label class="pl-field">What does the evidence support?<textarea name="note" rows="4" required maxlength="6000" placeholder="Observed change, suspected area, cause confirmation if established, action taken and retests">${esc(draft.note??job.handover?.note??'')}</textarea></label><label class="pl-field">Return visit / outstanding work<textarea name="outstanding" rows="3" maxlength="6000" placeholder="Missing documents, access, equipment, unresolved tests, remaining impairment">${esc(draft.outstanding??job.handover?.outstanding??'')}</textarea></label><button class="primary" type="submit">Save handover</button></form><details class="lfl-handover-preview" data-field-disclosure="handover-preview" open><summary>Copyable handover preview</summary><pre>${esc(typeof result.handoverSummary==='string'?result.handoverSummary:JSON.stringify(result.handoverSummary||{},null,2))}</pre>${button('copy-handover','Copy handover')}${button('export','Export log — without photo files')}</details><p class="pl-muted">This is your evidence record, not an automatic repair certificate or a declaration that protection has been restored.</p></section>`;}
 function history(){return `<details class="lfl-history" data-field-disclosure="history"><summary>Chronological job history · ${job.history.length}</summary><ol>${job.history.slice(-60).map((event,index)=>`<li><span>${dateLabel(event.at||event.createdAt||event.time)}</span><strong>${esc(event.summary||event.text||event.type||'Recorded change')}</strong>${event.reason?`<p>${esc(event.reason)}</p>`:''}<details><summary>Saved change details</summary><pre>${esc(JSON.stringify(event,null,2))}</pre></details></li>`).join('')}</ol>${job.history.length>60?'<p>Showing the latest 60 entries. Export includes the complete history.</p>':''}</details>`;}
 function paint(){
  if(!active())return;
  const disclosures=new Map([...mount.querySelectorAll('details[data-field-disclosure]')].map(item=>[item.dataset.fieldDisclosure,item.open]));
  const focused=document.activeElement,focus=mount.contains(focused)?focused.dataset.fieldFocus||focused.id:null;
  if(loadError){mount.innerHTML=`${header()}<div class="pl-notice pl-error" role="alert"><h3>Saved jobs could not be opened.</h3><p>${esc(loadError)}</p><p>Existing job records have not been replaced.</p>${button('reload','Try again')}</div>`;return;}
  if(!loaded){mount.innerHTML='<p role="status">Opening your saved loop investigations…</p>';return;}
  const section=currentUI().step||'capture';
  mount.innerHTML=`<div class="lfl-root">${header()}${jobsBar()}${error?`<div class="pl-notice pl-error" role="alert">${esc(error)}</div>`:''}${message?`<p class="pl-notice" role="status">${esc(message)}</p>`:''}<input type="file" id="lfl-import-file" accept="application/json,.json" hidden>${creating||!job?`<section class="lfl-create"><h3>Start a site investigation</h3>${detailsForm(true)}<div class="pl-actions">${job?button('cancel-create','Return to current job'):''}${button('import','Import an existing log')}</div></section>`:`${controls()}${section==='devices'?devices():section==='sections'?sections():section==='tests'?tests():section==='handover'?handover():capture()}${history()}`}</div>`;
  for(const detail of mount.querySelectorAll('details[data-field-disclosure]'))if(disclosures.has(detail.dataset.fieldDisclosure))detail.open=disclosures.get(detail.dataset.fieldDisclosure);
  if(pendingDelete)mount.querySelector('[data-field-disclosure="job-options"]')?.setAttribute('open','');
  if(focus){const target=mount.querySelector('#'+CSS.escape(focus))||mount.querySelector(`[data-field-focus="${CSS.escape(focus)}"]`);target?.focus({preventScroll:true});}
  if(job&&section==='capture')ensurePhoto();
 }
 async function selectJob(id){await flush();if(saveError||unsavedJob||pendingPhoto)throw Error('Save or export the current changes before switching jobs.');const own=++selectionEpoch;const next=await store.loadJob(id);if(own!==selectionEpoch)return;if(!next)throw Error('This saved job is no longer available. Reopen the job list.');revokePhoto();job=next;revisions.set(next.id,next.revision);remember(next);creating=false;pendingDelete=false;error='';message='';currentUI();persist(null);paint();}
 async function render(element){mount=element;const own=++epoch;if(!loaded&&!loading){loading=(async()=>{try{const [savedJobs,savedUI]=await Promise.all([store.listJobs(),read(UI_KEY)]);if(savedUI!==undefined){if(!savedUI||typeof savedUI!=='object'||Array.isArray(savedUI)||!savedUI.jobs||typeof savedUI.jobs!=='object'||Array.isArray(savedUI.jobs))throw Error('The saved field workspace cannot be read. Your job records are retained.');ui=savedUI;}jobs=savedJobs;revisions=new Map(jobs.map(item=>[item.id,item.revision]));const selected=jobs.find(item=>item.id===ui.selectedJobId)||jobs[0];if(selected){job=await store.loadJob(selected.id);currentUI();}loaded=true;loadError='';}catch(err){loadError=err?.message||'Storage is unavailable.';}finally{loading=null;}})();}if(loading){paint();await loading;}if(own===epoch){paint();refreshReadiness();}}
 function download(name,value,type='application/json'){const blob=value instanceof Blob?value:new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name.replace(/[\\/:*?"<>|]/g,'-');document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 async function startPhotos(files,{retryId=null}={}){
  for(const file of files){if(!file.size)throw Error('This photo is empty and was not saved. Choose the original photograph again.');if(file.size>30*1024*1024)throw Error('This photo is over 30 MB and was not saved. Choose a smaller copy.');}if(busy())throw Error('Finish or cancel the current photo reading first.');if(!job)throw Error('Create a job before adding its photos.');await flush();if(saveError)throw Error('Save this job before attaching more photos.');
  const importJobId=job.id,controller=new AbortController();processing=controller;processingStatus={message:'Preparing local photo reading…'};error='';message='';currentUI().step='capture';currentUI().reviewManual=false;paint();
  try{
   const results=await processLoopPhotos(files,{signal:controller.signal,...(retryId?{photoIds:[retryId]}:{}),onProgress:progress=>{processingStatus=progress;if(active()){const block=mount.querySelector('#lfl-processing-status');if(block){block.querySelector('strong').textContent=progress.message||'Reading your photograph…';let meter=block.querySelector('progress');if(Number.isFinite(progress.progress)){if(!meter){meter=document.createElement('progress');meter.max=1;meter.setAttribute('aria-label','Actual photo processing progress');block.querySelector('strong').after(meter);}meter.value=progress.progress;}else meter?.remove();}}},onPhotoStart:async(result,blob)=>{
    if(job?.id!==importJobId)throw Error('The active job changed. Reopen it before continuing this import.');const existing=job.photos.find(item=>item.id===result.photo.id),ocr=clone({...result,state:'pending'});
    job=updateFieldJob(job,existing?{type:'update-photo',id:existing.id,ocr}:{type:'add-photo',photo:result.photo,ocr});remember(job);currentUI().selectedPhotoId=result.photo.id;await persist(job,{photo:{id:result.photo.id,blob}});if(saveError)throw Error(saveError);paint();
   },onPhoto:async(result,blob)=>{
    if(job?.id!==importJobId)throw Error('The active job changed. The photo reading was not attached elsewhere.');const existing=job.photos.find(item=>item.id===result.photo.id),ocr=clone(result);job=updateFieldJob(job,existing?{type:'update-photo',id:existing.id,ocr}:{type:'add-photo',photo:result.photo,ocr});remember(job);await persist(job,existing?{}:{photo:{id:result.photo.id,blob}});if(saveError)throw Error(saveError);if(!currentUI().photoDrafts)currentUI().photoDrafts={};if(!currentUI().photoDrafts[result.photo.id]?.length)delete currentUI().photoDrafts[result.photo.id];currentUI().selectedPhotoId=result.photo.id;paint();
   }});
   const failures=results.filter(item=>item.error);if(failures.length)error=`${failures.length} photo${failures.length===1?'':'s'} need attention. ${failures[0].error.message} Saved originals remain available for manual review.`;else message='Photos read locally. Review the proposals against the originals before adding any devices.';
  }catch(err){error=err?.name==='AbortError'?'Photo reading cancelled. Photos and results already saved remain available. Retry a saved photo or enter its rows manually.':err?.message||'Photo reading could not finish. Saved originals and previous rows are kept.';}
  finally{if(processing===controller){processing=null;processingStatus=null;}paint();refreshReadiness();}
 }
 function captureForm(form){const data=new FormData(form),object=Object.fromEntries(data);for(const box of form.querySelectorAll('input[type="checkbox"]'))if(!['deviceIds','sectionIds'].includes(box.name))object[box.name]=box.checked;if(form.id==='lfl-section-form')object.deviceIds=data.getAll('deviceIds');if(form.id==='lfl-test-form'){object.sectionIds=data.getAll('sectionIds');object.coverage={};for(const [key,value]of data)if(key.startsWith('coverage:')){object.coverage[key.slice(9)]=value;delete object[key];}}if(form.dataset.id)object.id=form.dataset.id;return object;}
 function recordTest(data){return {sectionIds:data.getAll('sectionIds'),startedAt:data.get('startedAt')?new Date(String(data.get('startedAt'))).getTime():null,endedAt:data.get('endedAt')?new Date(String(data.get('endedAt'))).getTime():null,conditions:String(data.get('conditions')||''),conditionsConfirmed:data.has('conditionsConfirmed'),polledDeviceIds:job.devices.filter(item=>data.get('coverage:'+item.id)==='polled').map(item=>item.id),excludedDeviceIds:job.devices.filter(item=>data.get('coverage:'+item.id)==='excluded').map(item=>item.id),unavailableDeviceIds:job.devices.filter(item=>!['polled','excluded'].includes(data.get('coverage:'+item.id))).map(item=>item.id),missedBefore:numeric(data.get('missedBefore')),missedAfter:numeric(data.get('missedAfter')),reset:String(data.get('reset')||'none'),resetNote:String(data.get('resetNote')||''),pollsBefore:numeric(data.get('pollsBefore')),pollsAfter:numeric(data.get('pollsAfter')),pollsSource:String(data.get('pollsSource')||''),notes:String(data.get('notes')||'')};}
 app.addEventListener('click',async event=>{
  if(!active())return;const target=event.target.closest('[data-field-action]');if(!target||!mount.contains(target))return;const action=target.dataset.fieldAction;
  try{
   error='';
   if(action==='reload'){loaded=false;loadError='';await render(mount);return;}
   if(action==='resources'){if(openResources)await openResources({focus:'ocr',origin:{kind:'loop-field',jobId:job?.id||''}});else error='Local resource controls are not available in this view. Open Local resources from the app and prepare English OCR.';refreshReadiness();return;}
   if(action==='source'){const page=Number(target.dataset.page);if(onSource)await onSource({...sourceBase,pdfPage:page,printedPage:page,section:page===10?'Allocate Addresses / Map':'Loop Info / counters'});return;}
   if(action==='cancel-ocr'){processing?.abort();return;}
   if(['new-job','import','delete-job','confirm-delete'].includes(action)&&busy())throw Error('Cancel or finish photo reading before changing jobs.');
   if(action==='new-job'){await flush();if(saveError||unsavedJob||pendingPhoto)throw Error('Save or export the current changes before starting a new job.');creating=true;paint();return;}
   if(action==='cancel-create'){creating=false;paint();return;}
   if(action==='import'){mount.querySelector('#lfl-import-file').click();return;}
   if(action==='retry-save'){await persist(job);paint();return;}
   if(!job)return;
   if(action==='step'){setStep(target.dataset.id);return;}
   if(action==='export'){download((job.name||'loop-job')+'.findr-loop.json',exportFieldJob(job));toast('Log exported. Original photo files are not included.');return;}
   if(action==='delete-job'){pendingDelete=true;paint();return;}
   if(action==='cancel-delete'){pendingDelete=false;paint();return;}
   if(action==='confirm-delete'){await flush();if(saveError||unsavedJob||pendingPhoto)throw Error('Resolve or export unsaved changes before deleting this job.');await store.removeJob(job.id,{expectedRevision:revisions.get(job.id)??job.revision});delete ui.jobs[job.id];jobs=jobs.filter(item=>item.id!==job.id);job=null;pendingDelete=false;revokePhoto();if(jobs.length)job=await store.loadJob(jobs[0].id);await persist(null);paint();return;}
   if(action==='add-photos'){mount.querySelector('#lfl-photo-files').click();return;}
   if(action==='take-photo'){mount.querySelector('#lfl-camera-file').click();return;}
   if(action==='save-photo'){const photo=currentPhoto(),blob=pendingPhoto?.id===photo?.id?pendingPhoto.blob:await store.loadPhoto(job.id,photo.id);if(!blob)throw Error('This photo file is not available on this device. Its saved text is kept.');download(photo.name,blob,blob.type);return;}
   if(action==='retry-ocr'){const photo=currentPhoto(),blob=await store.loadPhoto(job.id,photo.id);if(!blob)throw Error('Choose the original photo again; its file is not stored on this device.');await startPhotos([new File([blob],photo.name,{type:photo.mimeType||blob.type})],{retryId:photo.id});return;}
   if(action==='manual-rows'){currentUI().reviewManual=true;currentUI().showPaste=false;if(!currentUI().manualRows?.length)currentUI().manualRows=[newRow()];persist(null);paint();return;}
   if(action==='paste-rows'){currentUI().showPaste=true;currentUI().reviewManual=true;paint();return;}
   if(action==='add-draft-row'){reviewRows().push(newRow({sourcePhotoIds:currentUI().reviewManual?[]:[currentPhoto().id]}));persist(null);paint();return;}
   if(action==='remove-draft-row'){const rows=reviewRows(),index=rows.findIndex(item=>item.id===target.dataset.id);if(index>=0)rows.splice(index,1);persist(null);paint();return;}
   if(action==='confirm-rows'){
    if(!mount.querySelector('#lfl-review-confirmed')?.checked)throw Error('Confirm that you checked the selected rows and that the source list belongs to this panel, card and loop.');const rows=reviewRows().filter(row=>row.include!==false);if(!rows.length)throw Error('Select at least one reviewed row.');let next=job;for(const row of rows)next=updateFieldJob(next,{type:'add-device',device:{address:numeric(row.address),mapNode:numeric(row.mapNode),label:String(row.label||''),isolator:row.isolator==='yes'?true:row.isolator==='no'?false:null,sourcePhotoIds:row.sourcePhotoIds||[],engineerConfirmed:true,notes:'Engineer reviewed the source list and confirmed panel/card/loop identity.'}});job=next;remember(job);const all=reviewRows();for(const row of rows)row.include=false;message=`${rows.length} reviewed rows added. Inventory completeness still needs a separate check.`;await persist();paint();return;
   }
   if(action==='edit-device'){currentUI().editDevice=target.dataset.id;currentUI().deviceDraft={};paint();mount.querySelector('#lfl-device-form')?.scrollIntoView({block:'start'});return;}
   if(action==='cancel-device'){currentUI().editDevice='';currentUI().deviceDraft={};persist(null);paint();return;}
   if(action==='remove-device'){const reason=mount.querySelector('#lfl-device-form [name="reason"]')?.value||'';change({type:'remove-device',id:target.dataset.id,reason});currentUI().editDevice='';paint();return;}
   if(action==='edit-section'){currentUI().sectionDraft=clone(job.sections.find(item=>item.id===target.dataset.id));paint();mount.querySelector('#lfl-section-form')?.scrollIntoView({block:'start'});return;}
   if(action==='clear-section'){currentUI().sectionDraft={};persist(null);paint();return;}
   if(action==='edit-test'){const test=job.tests.find(item=>item.id===target.dataset.id);currentUI().testDraft={...clone(test),startedAt:localDate(test.startedAt),endedAt:localDate(test.endedAt),coverage:Object.fromEntries(job.devices.map(item=>[item.id,test.polledDeviceIds.includes(item.id)?'polled':test.excludedDeviceIds.includes(item.id)?'excluded':'unavailable']))};paint();mount.querySelector('#lfl-test-form')?.scrollIntoView({block:'start'});return;}
   if(action==='clear-test'){currentUI().testDraft={};persist(null);paint();return;}
   if(action==='time-start'||action==='time-end'){const name=action==='time-start'?'startedAt':'endedAt',element=mount.querySelector(`#lfl-test-form [name="${name}"]`);element.value=localDate(Date.now());currentUI().testDraft=captureForm(element.form);saveDraftSoon();return;}
   if(action==='coverage-all-polled'){const form=mount.querySelector('#lfl-test-form');for(const element of form.querySelectorAll('select[name^="coverage:"]'))element.value='polled';currentUI().testDraft=captureForm(form);saveDraftSoon();return;}
   if(action==='copy-handover'){await navigator.clipboard.writeText(view().handoverSummary);toast('Handover copied.');return;}
  }catch(err){error=err?.message||'That action could not be completed. The open job is kept.';paint();}
 });
 app.addEventListener('input',event=>{
  if(!active())return;const target=event.target,row=target.closest('[data-review-row]');
  if(row&&job){const draft=reviewRows().find(item=>item.id===row.dataset.reviewRow);if(draft){draft[target.name]=target.type==='checkbox'?target.checked:target.value;saveDraftSoon();}return;}
  const form=target.closest('form');if(!form)return;
  if(form.id==='lfl-job-form'){if(form.dataset.new==='true')ui.createDraft=captureForm(form);else currentUI().jobDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-device-form'){currentUI().deviceDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-inventory-form'){currentUI().inventoryDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-section-form'){currentUI().sectionDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-test-form'){currentUI().testDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-handover-form'){currentUI().handoverDraft=captureForm(form);saveDraftSoon();}
  else if(job&&form.id==='lfl-paste-form'){currentUI().paste=target.value;saveDraftSoon();}
 });
 app.addEventListener('change',async event=>{
  if(!active())return;const target=event.target;
  try{
   if(target.id==='lfl-job-select'&&target.value){if(busy())throw Error('Finish or cancel reading photos first.');await selectJob(target.value);}
   else if(target.id==='lfl-photo-select'){currentUI().selectedPhotoId=target.value;currentUI().reviewManual=false;revokePhoto();persist(null);paint();}
   else if(['lfl-photo-files','lfl-camera-file'].includes(target.id)){const files=[...target.files||[]];target.value='';if(files.length)await startPhotos(files);else{message='No photo selected. Your job is unchanged.';paint();}}
   else if(target.id==='lfl-import-file'){const file=target.files?.[0];target.value='';if(!file)return;if(file.size>20*1024*1024)throw Error('Choose a FINDR loop-job JSON under 20 MB.');await flush();if(saveError||unsavedJob||pendingPhoto)throw Error('Save or export current changes before importing another job.');const own=epoch,text=await file.text();if(!active()||own!==epoch)return;const imported=importFieldJob(text);revokePhoto();job=imported;remember(job);creating=false;currentUI().step='devices';message='Imported as a separate job. Original photo files are not included; reviewed text and history are retained.';await persist();paint();}
  }catch(err){error=err?.message||'That file could not be opened.';paint();}
 });
 app.addEventListener('submit',async event=>{
  if(!active())return;const form=event.target;if(!form.matches('#lfl-job-form,#lfl-paste-form,#lfl-device-form,#lfl-inventory-form,#lfl-section-form,#lfl-test-form,#lfl-impairment-form,.lfl-restoration-form,#lfl-handover-form'))return;event.preventDefault();
  try{
   const data=new FormData(form);error='';message='';
   if(form.id==='lfl-job-form'){const details=Object.fromEntries(['name','panel','card','loop','reference'].map(name=>[name,String(data.get(name)||'')]));if(form.dataset.new==='true'){await flush();if(saveError)throw Error('Save the current changes first.');job=createFieldJob(details);remember(job);ui.createDraft={};creating=false;currentUI();await persist();paint();}else{currentUI().jobDraft={};change({type:'details',patch:details});}return;}
   if(!job)return;
   if(form.id==='lfl-paste-form'){const text=String(data.get('text')||''),parsed=parseLoopListText(text,{sourcePhotoId:'',confidence:null});currentUI().paste=text;currentUI().manualRows=(parsed.suggestions||[]).map(row=>newRow({id:row.id||uid(),address:row.address??'',mapNode:row.map??row.mapNode??'',label:row.locationText||'',rawLine:row.rawLine||'',issues:row.issues||[]}));currentUI().reviewManual=true;message=parsed.warnings?.join(' ')||'Review the proposed columns before confirming.';if(!currentUI().manualRows.length)currentUI().manualRows=[newRow({rawLine:text})];persist(null);paint();}
   else if(form.id==='lfl-device-form'){const patch={address:numeric(data.get('address')),mapNode:numeric(data.get('mapNode')),label:String(data.get('label')||''),isolator:data.get('isolator')==='yes'?true:data.get('isolator')==='no'?false:null};job=updateFieldJob(job,{type:'correct-device',id:form.dataset.id,patch,reason:String(data.get('reason')||'')});currentUI().editDevice='';currentUI().deviceDraft={};remember(job);persist();paint();}
   else if(form.id==='lfl-inventory-form'){job=updateFieldJob(job,{type:'inventory-scope',inventoryComplete:data.has('inventoryComplete'),expectedDeviceCount:numeric(data.get('expectedDeviceCount')),confirmation:String(data.get('confirmation')||'')});currentUI().inventoryDraft={};remember(job);persist();paint();}
   else if(form.id==='lfl-section-form'){const section={name:String(data.get('name')||''),deviceIds:data.getAll('deviceIds'),topologyEvidence:String(data.get('topologyEvidence')||''),topologyConfirmed:data.has('topologyConfirmed')};job=updateFieldJob(job,form.dataset.id?{type:'correct-section',id:form.dataset.id,patch:section,reason:String(data.get('reason')||'')}:{type:'add-section',section});remember(job);currentUI().sectionDraft={};persist();paint();}
   else if(form.id==='lfl-test-form'){const test=recordTest(data);job=updateFieldJob(job,form.dataset.id?{type:'correct-test',id:form.dataset.id,patch:test,reason:String(data.get('reason')||'')}:{type:'add-test',test});remember(job);currentUI().testDraft={};message='Actual observation saved with its original inventory, conditions and coverage.';persist();paint();}
   else if(form.id==='lfl-impairment-form')change({type:'add-impairment',impairment:{description:String(data.get('description')||'')}});
   else if(form.matches('.lfl-restoration-form'))change({type:'restore-impairment',id:form.dataset.id,evidence:String(data.get('evidence')||'')});
   else if(form.id==='lfl-handover-form'){change({type:'handover',note:String(data.get('note')||''),outstanding:String(data.get('outstanding')||'')});message='Handover saved. Review its outstanding work before export.';paint();}
  }catch(err){error=err?.message||'That record could not be saved.';paint();}
 });
 return {render,leave(){epoch++;selectionEpoch++;processing?.abort();if(draftTimer){clearTimeout(draftTimer);draftTimer=null;persist(null);}revokePhoto();mount=null;},getJob(){return job?clone(job):null;}};
}
